(function(){
  function dump(text){
    text=String(text==null?'':text);
    var bytes=[]; for(var i=0;i<text.length;i++){ var c=text.charCodeAt(i);
      if(c<0x80)bytes.push(c); else if(c<0x800){bytes.push(0xC0|(c>>6),0x80|(c&0x3F));}
      else if(c>=0xD800&&c<=0xDBFF){var c2=text.charCodeAt(++i);var cp=0x10000+((c&0x3FF)<<10)+(c2&0x3FF);bytes.push(0xF0|(cp>>18),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F));}
      else {bytes.push(0xE0|(c>>12),0x80|((c>>6)&0x3F),0x80|(c&0x3F));} }
    var lines=[];
    for(var o=0;o<bytes.length;o+=16){
      var slice=bytes.slice(o,o+16);
      var hex=slice.map(function(b){return ('0'+b.toString(16)).slice(-2);}).join(' ');
      while(hex.length<47) hex+=' ';
      var asc=slice.map(function(b){return (b>=0x20&&b<0x7F)? String.fromCharCode(b):'.';}).join('');
      lines.push(('00000000'+o.toString(16)).slice(-8)+'  '+hex+'  |'+asc+'|');
    }
    if(bytes.length===0) lines.push('00000000');
    return {value:lines.join('\n')};
  }
  var API={dump:dump};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__HexdumpForge__=API;
})();
